#!/usr/bin/env node

const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// --- Color helpers ---
const C = {
  red: s => `\x1b[31m${s}\x1b[0m`,
  green: s => `\x1b[32m${s}\x1b[0m`,
  yellow: s => `\x1b[33m${s}\x1b[0m`,
  blue: s => `\x1b[34m${s}\x1b[0m`,
  magenta: s => `\x1b[35m${s}\x1b[0m`,
  cyan: s => `\x1b[36m${s}\x1b[0m`,
  gray: s => `\x1b[90m${s}\x1b[0m`,
  bold: s => `\x1b[1m${s}\x1b[0m`,
  dim: s => `\x1b[2m${s}\x1b[0m`,
};

function git(args) {
  try {
    return execSync(`git ${args}`, { encoding: 'utf8', stdio: ['pipe', 'pipe', 'pipe'] }).trim();
  } catch {
    return '';
  }
}

function gitLines(args) {
  const out = git(args);
  return out ? out.split('\n') : [];
}

// --- Commands ---

function cmdList(opts) {
  const { sort = 'age', remote = false, limit = 20 } = opts;
  const prefix = remote ? '-r' : '';
  const currentBranch = git('rev-parse --abbrev-ref HEAD');

  let branches = gitLines(`for-each-ref ${prefix} --sort=-committerdate --format='%(refname:short)|%(committerdate:unix)|%(committerdate:relative)|%(authorname)|%(objectname:short)' refs/heads/ ${remote ? 'refs/remotes/' : ''}`);

  if (remote) {
    // filter out HEAD references
    branches = branches.filter(b => !b.endsWith('/HEAD'));
  }

  // parse
  let parsed = branches.map(line => {
    const [name, ts, relative, author, sha] = line.split('|');
    return { name, ts: parseInt(ts, 10), relative, author, sha };
  });

  if (sort === 'age') parsed.sort((a, b) => a.ts - b.ts); // oldest first
  else if (sort === 'newest') parsed.sort((a, b) => b.ts - a.ts);
  else if (sort === 'name') parsed.sort((a, b) => a.name.localeCompare(b.name));

  if (limit > 0) parsed = parsed.slice(0, limit);

  const now = Math.floor(Date.now() / 1000);
  console.log(C.bold(`\n  Branches (sorted by ${sort})\n`));
  console.log(`  ${C.dim('BRANCH'.padEnd(35))} ${C.dim('AGE'.padEnd(14))} ${C.dim('AUTHOR'.padEnd(18))} ${C.dim('SHA')}`);
  console.log(`  ${C.gray('─'.repeat(82))}`);

  for (const b of parsed) {
    const ageDays = Math.floor((now - b.ts) / 86400);
    let ageColor = C.green;
    if (ageDays > 90) ageColor = C.red;
    else if (ageDays > 30) ageColor = C.yellow;

    const marker = b.name === currentBranch ? C.green(' *') : '  ';
    const nameCol = b.name === currentBranch ? C.bold(C.green(b.name)) : C.cyan(b.name);
    const branchDisplay = remote ? b.name.replace(/^origin\//, C.dim('origin/') + C.cyan) : nameCol;

    console.log(`${marker} ${typeof branchDisplay === 'string' ? branchDisplay.padEnd(37) : branchDisplay} ${ageColor(b.relative.padEnd(14))} ${C.dim(b.author.padEnd(18))} ${C.gray(b.sha)}`);
  }
  console.log();
}

function cmdStale(opts) {
  const { days = 30, remote = false } = opts;
  const prefix = remote ? '-r' : '';
  const now = Math.floor(Date.now() / 1000);
  const threshold = days * 86400;

  let branches = gitLines(`for-each-ref ${prefix} --sort=committerdate --format='%(refname:short)|%(committerdate:unix)|%(committerdate:relative)|%(authorname)' refs/heads/ ${remote ? 'refs/remotes/' : ''}`);
  if (remote) branches = branches.filter(b => !b.endsWith('/HEAD'));

  const stale = branches.map(line => {
    const [name, ts, relative, author] = line.split('|');
    return { name, ts: parseInt(ts, 10), relative, author };
  }).filter(b => (now - b.ts) > threshold);

  if (!stale.length) {
    console.log(C.green(`\n  ✓ No branches older than ${days} days.\n`));
    return;
  }

  console.log(C.bold(`\n  ⚠ Stale branches (> ${days} days)\n`));
  console.log(`  ${C.dim('BRANCH'.padEnd(40))} ${C.dim('AGE'.padEnd(14))} ${C.dim('AUTHOR')}`);
  console.log(`  ${C.gray('─'.repeat(75))}`);

  for (const b of stale) {
    const ageDays = Math.floor((now - b.ts) / 86400);
    const ageColor = ageDays > 90 ? C.red : C.yellow;
    console.log(`  ${C.red(b.name.padEnd(40))} ${ageColor(b.relative.padEnd(14))} ${C.dim(b.author)}`);
  }
  console.log(C.dim(`\n  Total: ${stale.length} stale branch(es)\n`));
}

function cmdMerged(opts) {
  const { target = 'main', remote = false, dryRun = true } = opts;
  const prefix = remote ? '-r' : '';
  const currentBranch = git('rev-parse --abbrev-ref HEAD');

  // get merged branches
  let merged = gitLines(`branch ${prefix} --merged ${target}`);
  merged = merged.map(b => b.replace(/^\*?\s*/, '').trim()).filter(b => b && b !== target && b !== currentBranch);

  if (remote) merged = merged.filter(b => !b.endsWith('/HEAD'));

  if (!merged.length) {
    console.log(C.green(`\n  ✓ No branches merged into ${target}.\n`));
    return;
  }

  console.log(C.bold(`\n  Branches merged into ${C.cyan(target)}\n`));
  console.log(`  ${C.dim('BRANCH'.padEnd(40))} ${C.dim('STATUS')}`);
  console.log(`  ${C.gray('─'.repeat(55))}`);

  for (const b of merged) {
    console.log(`  ${C.yellow(b.padEnd(40))} ${C.red('merged')}`);
  }
  console.log(C.dim(`\n  Total: ${merged.length} merged branch(es)\n`));

  if (dryRun) {
    console.log(C.dim(`  (dry-run) Use --delete to remove these branches.\n`));
  } else if (opts.delete) {
    const deleted = [];
    for (const b of merged) {
      const flag = remote ? '' : '';
      const fullRef = remote ? b : b;
      const result = git(`branch ${remote ? '-r -d' : '-d'} ${remote ? b : b}`);
      if (result || !git(`show-ref ${fullRef}`)) {
        deleted.push(b);
        console.log(`  ${C.red('deleted')} ${b}`);
      } else {
        console.log(`  ${C.yellow('skipped')} ${b} (not fully merged or error)`);
      }
    }
    console.log(C.green(`\n  Deleted ${deleted.length} branch(es).\n`));
  }
}

function cmdCompare(args) {
  const [a, b] = args;
  if (!a || !b) {
    console.log(C.red('\n  Usage: git-branch-cli compare <branch-a> <branch-b>\n'));
    process.exit(1);
  }

  // resolve current branch if "."
  const resolve = name => name === '.' ? git('rev-parse --abbrev-ref HEAD') : name;
  const branchA = resolve(a);
  const branchB = resolve(b);

  console.log(C.bold(`\n  Comparing ${C.cyan(branchA)} ↔ ${C.magenta(branchB)}\n`));

  const mergeBase = git(`merge-base ${branchA} ${branchB}`);
  if (!mergeBase) {
    console.log(C.red('  No common ancestor found.\n'));
    return;
  }

  // commits ahead/behind
  const aheadA = git(`rev-list --count ${mergeBase}..${branchA}`);
  const aheadB = git(`rev-list --count ${mergeBase}..${branchB}`);
  const totalDivergence = parseInt(aheadA, 10) + parseInt(aheadB, 10);

  console.log(`  ${C.cyan(branchA)}: ${C.green(aheadA)} commit(s) ahead of merge-base`);
  console.log(`  ${C.magenta(branchB)}: ${C.green(aheadB)} commit(s) ahead of merge-base`);
  console.log(`  ${C.dim('Divergence: ' + totalDivergence + ' commit(s)')}\n`);

  // diff stats
  const diff = git(`diff --stat ${branchA}...${branchB}`);
  if (diff) {
    console.log(`  ${C.bold('Diff stats')}`);
    for (const line of diff.split('\n')) {
      console.log(`  ${line}`);
    }
  }

  // changed files
  const files = gitLines(`diff --name-status ${branchA}...${branchB}`);
  if (files.length) {
    console.log(`\n  ${C.bold('Changed files')}`);
    for (const f of files) {
      const [status, ...nameParts] = f.split('\t');
      const name = nameParts.join('\t');
      let statusColor = C.dim;
      if (status.startsWith('A')) statusColor = C.green;
      else if (status.startsWith('D')) statusColor = C.red;
      else if (status.startsWith('M')) statusColor = C.yellow;
      console.log(`  ${statusColor(status.padEnd(2))} ${name}`);
    }
  }
  console.log();
}

function cmdPrune(opts) {
  const { remote = 'origin', dryRun = true } = opts;
  console.log(C.bold(`\n  Pruning deleted remote-tracking branches from ${C.cyan(remote)}\n`));

  const before = gitLines(`branch -r`).filter(b => b.startsWith(`${remote}/`) && !b.endsWith('/HEAD'));

  git(`fetch ${remote} --prune`);

  const after = gitLines(`branch -r`).filter(b => b.startsWith(`${remote}/`) && !b.endsWith('/HEAD'));
  const removed = before.filter(b => !after.includes(b));

  if (!removed.length) {
    console.log(C.green('  ✓ No stale tracking branches to prune.\n'));
    return;
  }

  for (const b of removed) {
    console.log(`  ${C.red('pruned')} ${b}`);
  }
  console.log(C.dim(`\n  Pruned ${removed.length} stale tracking branch(es).\n`));
}

// --- CLI parsing ---

function parseArgs() {
  const argv = process.argv.slice(2);
  const command = argv[0] || 'help';
  const flags = {};

  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--sort' || arg === '-s') flags.sort = argv[++i];
    else if (arg === '--target' || arg === '-t') flags.target = argv[++i];
    else if (arg === '--days' || arg === '-d') flags.days = parseInt(argv[++i], 10);
    else if (arg === '--limit' || arg === '-l') flags.limit = parseInt(argv[++i], 10);
    else if (arg === '--remote' || arg === '-r') flags.remote = true;
    else if (arg === '--delete' || arg === '-x') flags.delete = true;
    else if (arg === '--dry-run' || arg === '-n') flags.dryRun = true;
    else if (arg === '--no-dry-run') flags.dryRun = false;
    else if (!arg.startsWith('-')) flags.positional = flags.positional || [];
  }

  // collect positional args
  flags.positional = argv.slice(1).filter(a => !a.startsWith('-'));

  return { command, flags };
}

function showHelp() {
  console.log(`
  ${C.bold('git-branch-cli')} — Git branch management tool

  ${C.bold('USAGE')}
    git-branch-cli <command> [options]

  ${C.bold('COMMANDS')}
    ${C.cyan('list')}      List branches (default). Sort by age, newest, or name.
    ${C.cyan('stale')}     Find branches older than N days (default: 30).
    ${C.cyan('merged')}    List branches merged into a target (default: main).
    ${C.cyan('compare')}   Compare two branches (commits, files, diff).
    ${C.cyan('prune')}     Prune stale remote-tracking branches.
    ${C.cyan('help')}      Show this help.

  ${C.bold('OPTIONS')}
    ${C.dim('--sort, -s')}      Sort: age | newest | name (default: age)
    ${C.dim('--target, -t')}    Target branch for merged (default: main)
    ${C.dim('--days, -d')}      Stale threshold in days (default: 30)
    ${C.dim('--limit, -l')}     Max branches to show (default: 20, 0=all)
    ${C.dim('--remote, -r')}    Include remote branches
    ${C.dim('--delete, -x')}    Actually delete merged branches
    ${C.dim('--dry-run, -n')}   Only show what would be deleted (default)
    ${C.dim('--no-dry-run')}    Disable dry-run

  ${C.bold('EXAMPLES')}
    git-branch-cli list --sort newest -l 10
    git-branch-cli stale --days 60
    git-branch-cli merged --target main --remote --delete
    git-branch-cli compare feature/login develop
    git-branch-cli prune
`);
}

// --- Main ---

function main() {
  // Check we're in a git repo
  if (!git('rev-parse --git-dir')) {
    console.error(C.red('\n  Error: not a git repository.\n'));
    process.exit(1);
  }

  const { command, flags } = parseArgs();

  switch (command) {
    case 'list':
    case 'ls':
      cmdList(flags);
      break;
    case 'stale':
      cmdStale(flags);
      break;
    case 'merged':
      cmdMerged(flags);
      break;
    case 'compare':
    case 'diff':
      cmdCompare(flags.positional);
      break;
    case 'prune':
      cmdPrune(flags);
      break;
    case 'help':
    case '--help':
    case '-h':
      showHelp();
      break;
    default:
      console.error(C.red(`\n  Unknown command: ${command}\n`));
      showHelp();
      process.exit(1);
  }
}

main();

